import React, { useEffect, useRef, useState, useSyncExternalStore } from 'react';
import { resolveSlotLabel } from '@deepseek-ai/dsh-client-ui-slots';
import { GROUPS, STORAGE_KEY, groupFor, parsePreferences, hiddenLabels, cssString } from './model.mjs';
import css from './style.css';

const NS = 'sidebar-categories';
const zh = { work: '工作', manage: '个人', develop: '开发', categories: '功能分类', settings: '设置入口分类', title: '入口分类', hint: '为每个入口选择分类。新入口默认归入工作；设置保存在当前浏览器。', done: '完成', reset: '恢复默认分类', storage: '浏览器未允许保存，下次打开时可能恢复默认。' };
const en = { work: 'Work', manage: 'Personal', develop: 'Develop', categories: 'Navigation categories', settings: 'Organize entries', title: 'Organize entries', hint: 'Choose a category for each entry. New entries default to Work. Preferences are saved in this browser.', done: 'Done', reset: 'Reset categories', storage: 'Storage is unavailable. Preferences may reset next time.' };
export const inject = ['slots', 'locale'];

export function apply(ctx) {
  ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'sidebar-categories:locale');
  const t = ctx.locale.bind(NS);
  ctx.slots.inject('sidebar.session.action', () => {
    let snapshot = [];
    const listeners = new Set();
    const sync = () => {
      const next = ctx.slots.entriesOfSlot('sidebar.panellist').map(({ options }) => ({
        id: options.id, label: resolveSlotLabel(options.label) ?? options.id, order: options.order ?? 0,
      })).sort((a, b) => a.order - b.order);
      if (JSON.stringify(snapshot) === JSON.stringify(next)) return;
      snapshot = next;
      for (const listener of listeners) listener();
    };
    const panelsSource = { subscribe: listener => { listeners.add(listener); return () => listeners.delete(listener); }, getSnapshot: () => snapshot };
    sync();
    const unsubscribePanels = ctx.slots.subscribe('sidebar.panellist', sync);
    const unsubscribeLocale = ctx.locale.subscribe(sync);
    const subscribeLocale = listener => ctx.locale.subscribe(listener);
    const localeSnapshot = () => ctx.locale.getSnapshot();

    function CategoryNavigation({ children, wide, usePanelInfo }) {
      useSyncExternalStore(subscribeLocale, localeSnapshot);
      const allPanels = useSyncExternalStore(panelsSource.subscribe, panelsSource.getSnapshot);
      const activePanel = usePanelInfo(info => info.activePanelId);
      const [preferences, setPreferences] = useState(() => {
        try { return parsePreferences(localStorage.getItem(STORAGE_KEY)); }
        catch { return parsePreferences(null); }
      });
      const [storageFailed, setStorageFailed] = useState(false);
      const [editing, setEditing] = useState(false);
      const dialog = useRef(null);
      const launcher = useRef(null);
      const group = preferences.selected;
      useEffect(() => {
        try { localStorage.setItem(STORAGE_KEY, JSON.stringify(preferences)); setStorageFailed(false); }
        catch { setStorageFailed(true); }
      }, [preferences]);
      useEffect(() => {
        const syncStorage = event => { if (event.key === STORAGE_KEY) setPreferences(parsePreferences(event.newValue)); };
        window.addEventListener('storage', syncStorage);
        return () => window.removeEventListener('storage', syncStorage);
      }, []);
      useEffect(() => {
        const panel = allPanels.find(panel => panel.id === activePanel);
        if (panel) setPreferences(previous => ({ ...previous, selected: groupFor(panel, previous.assignments) }));
      }, [activePanel]);
      useEffect(() => { if (editing) dialog.current?.showModal(); }, [editing]);
      useEffect(() => { if (!wide) { dialog.current?.close(); setEditing(false); } }, [wide]);
      const closeEditor = () => { dialog.current?.close(); setEditing(false); launcher.current?.focus(); };
      const selectGroup = selected => setPreferences(previous => ({ ...previous, selected }));
      // Scope styles to the documented expanded-sidebar viewport and exact launcher labels.
      // Duplicate labels stay visible to avoid hiding an unrelated panel.
      const filterCss = wide ? hiddenLabels(allPanels, preferences).map(label =>
        `[data-sidebar-scrollport] > nav > div:has(button[aria-label=${cssString(label)}]){display:none!important}`
      ).join('\n') : '';

      if (!wide) return children;
      return <div className="dsc-session-stack"><style>{css + '\n' + filterCss}</style>
        <div className="dsc-original-session">{children}</div>
        <div className="dsc-categories">
          <div className="dsc-tabs" role="group" aria-label={t('categories')}>
            {GROUPS.map((key, index) => <button key={key} type="button" aria-pressed={key === group}
              data-category={key} onClick={() => selectGroup(key)} onKeyDown={event => {
                if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
                event.preventDefault();
                const next = event.key === 'Home' ? 0 : event.key === 'End' ? 2 : (index + (event.key === 'ArrowRight' ? 1 : 2)) % 3;
                selectGroup(GROUPS[next]); event.currentTarget.parentElement.querySelectorAll('button')[next].focus();
              }}><span aria-hidden="true">{['☷', '▦', '‹›'][index]}</span>{t(key)}</button>)}
          </div>
          <button type="button" className="dsc-config" ref={launcher} aria-label={t('settings')} title={t('settings')} onClick={() => setEditing(true)}>
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="var(--dsw-alias-button-elevated-fill)"/><circle cx="15" cy="17" r="3" fill="var(--dsw-alias-button-elevated-fill)"/></svg>
          </button>
        </div>
        {editing && <dialog ref={dialog} className="dsc-dialog" aria-labelledby="dsc-title" onCancel={event => { event.preventDefault(); closeEditor(); }} onClose={() => { setEditing(false); launcher.current?.focus(); }}>
          <h2 id="dsc-title">{t('title')}</h2><p>{t('hint')}</p>
          <div className="dsc-assignments">{allPanels.map(panel => <label className="dsc-assignment" key={panel.id}>
            <span title={panel.id}>{panel.label}</span><select aria-label={panel.label} value={groupFor(panel, preferences.assignments)} onChange={event => {
              const value = event.target.value; setPreferences(previous => ({ ...previous, assignments: { ...previous.assignments, [panel.id]: value } }));
            }}>{GROUPS.map(key => <option value={key} key={key}>{t(key)}</option>)}</select>
          </label>)}</div>
          {storageFailed && <p role="status">{t('storage')}</p>}
          <div className="dsc-dialog-actions"><button type="button" onClick={() => setPreferences(previous => ({ ...previous, assignments: {} }))}>{t('reset')}</button><button type="button" className="dsc-done" onClick={closeEditor}>{t('done')}</button></div>
        </dialog>}
      </div>;
    }
    let unregister;
    try {
      unregister = ctx.slots.register({ name: 'sidebar.session.action', id: 'sidebar-categories', order: -100, locale: NS }, CategoryNavigation);
    } catch (error) { unsubscribePanels(); unsubscribeLocale(); throw error; }
    return () => { unregister(); unsubscribePanels(); unsubscribeLocale(); listeners.clear(); };
  });
}
